// === Tab: mySketch ===
// シンプレックスに出てくる変換を研究する（3次元）

// 可視化したけど可視化になってないなこれ

let myShader;
let properFrameCount = 0;

let vs =
"precision mediump float;" +
"attribute vec3 aPosition;" +
"void main(void){" +
"  gl_Position = vec4(aPosition, 1.0);" +
"}";

let fs =
"precision mediump float;" +
"uniform vec2 u_resolution;" +
"uniform vec2 u_mouse;" +
"uniform float u_time;" +
"const float pi = 3.14159;" +
"const vec3 r_vec_1 = vec3(127.1, 311.7, 251.9);" +
"const vec3 r_vec_2 = vec3(269.5, 183.3, 314.3);" +
"const vec3 r_vec_3 = vec3(419.2, 371.9, 218.4);" +
"const vec3 u_100 = vec3(1.0, 0.0, 0.0);" +
"const vec3 u_010 = vec3(0.0, 1.0, 0.0);" +
"const vec3 u_001 = vec3(0.0, 0.0, 1.0);" +
"const vec3 u_110 = vec3(1.0, 1.0, 0.0);" +
"const vec3 u_101 = vec3(1.0, 0.0, 1.0);" +
"const vec3 u_011 = vec3(0.0, 1.0, 1.0);" +
"const vec3 u_111 = vec3(1.0, 1.0, 1.0);" +
"const float r_coeff = 43758.5453123;" +
// 3Dランダムベクトル(-1.0～1.0)
"vec3 random3(vec3 st){" +
"  vec3 v;" +
"  v.x = sin(dot(st, r_vec_1)) * r_coeff;" +
"  v.y = sin(dot(st, r_vec_2)) * r_coeff;" +
"  v.z = sin(dot(st, r_vec_3)) * r_coeff;" +
"  return -1.0 + 2.0 * fract(v);" + // -1.0～1.0に正規化
"}" +
// hsbで書かれた(0.0～1.0)の数値vec3をrgbに変換する魔法のコード
"vec3 getHSB(float r, float g, float b){" +
"    vec3 c = vec3(r, g, b);" +
"    vec3 rgb = clamp(abs(mod(c.x * 6.0 + vec3(0.0, 3.7, 2.0), 6.0) - 3.0) - 1.0, 0.0, 1.0);" +
"    rgb = rgb * rgb * (3.0 - 2.0 * rgb);" +
"    return c.z * mix(vec3(1.0), rgb, c.y);" +
"}" +
"void main(void){" +
"  vec2 st = gl_FragCoord.xy * 0.4 / min(u_resolution.x, u_resolution.y);" +
"  st *= 6.0;" +
"  st -= 5.0;" +
"  float angle = u_time * pi * 0.03;" +
"  st *= mat2(cos(angle), -sin(angle), sin(angle), cos(angle));" +
"  vec3 q = vec3(st.x, st.y, u_time * 0.5);" +
"  vec3 p = q + (q.x + q.y + q.z) / 3.0;" +
"  vec3 f = fract(p);" +
"  vec3 i = floor(p);" +
"  float hue = 1.0;" +
"  if(f.x > f.y && f.x > f.z){" +
"    hue = (f.y > f.z ? 0.1 : 0.13);" +
"  }else if(f.y > f.x && f.y > f.z){" +
"    hue = (f.x > f.z ? 0.05 : 0.1);" +
"  }else{" +
"    hue = (f.x > f.y ? 0.0 : 0.05);" +
"  }" +
"  gl_FragColor = vec4(getHSB(hue, (f.x + f.y + f.z) * 0.5, 0.9), 1.0);" +
"}";

function setup(){
  createCanvas(1112, 834, WEBGL);
  myShader = createShader(vs, fs);
  shader(myShader);
}

function draw(){
  myShader.setUniform("u_resolution", [width, height]);
  myShader.setUniform("u_mouse", [(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))]);
  myShader.setUniform("u_time", properFrameCount / 60);
  quad(-1, -1, -1, 1, 1, 1, 1, -1);
  properFrameCount++;
}

function mousePressed(){save('pix.jpg'); }

